"""Windows 與 macOS 的路徑契約；不改寫使用者環境或系統設定。"""
from __future__ import annotations

import os
from pathlib import Path
import sys


def cache_root() -> Path:
    if sys.platform == 'win32':
        return Path(os.environ.get('LOCALAPPDATA', Path.home() / 'AppData' / 'Local')) / 'video-use'
    return Path.home() / 'Library' / 'Caches' / 'video-use'


def data_root() -> Path:
    if sys.platform == 'win32':
        return Path(os.environ.get('LOCALAPPDATA', Path.home() / 'AppData' / 'Local')) / 'video-use' / 'data'
    return Path.home() / 'Library' / 'Application Support' / 'video-use'


def venv_python(root: Path) -> Path:
    return root / 'Scripts' / 'python.exe' if sys.platform == 'win32' else root / 'bin' / 'python'


def fonts_root() -> Path:
    return Path(os.environ.get('WINDIR', 'C:/Windows')) / 'Fonts' if sys.platform == 'win32' else Path('/System/Library/Fonts')

SUB_FONTS_DIR = fonts_root()
if sys.platform == "win32":
    SUB_FORCE_STYLE = SUB_FORCE_STYLE.replace("Heiti TC", "Microsoft JhengHei")
